// Smart Pointer Emulation (Shared Pointer Control Block)

typedef struct {
    void* resource; // Managed data pointer
} ManagedResource;

typedef struct {
    ManagedResource* ptr;
    volatile int ref_count; // Atomic increment/decrement critical
} RefControlBlock;

// Assume resource cleanup function exists: free_resource(ptr)

void ref_acquire(RefControlBlock* rcb) {
    if (rcb) rcb->ref_count++;
}

void ref_release(RefControlBlock* rcb) {
    if (!rcb) return;

    rcb->ref_count--;

    if (rcb->ref_count == 0) {
        free_resource(rcb->ptr);
        free(rcb); // Release the control block
    }
}
